from itertools import combinations
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(2, 5))
    rows = []
    for _ in range(n):
        rows.append(draw(st.text(alphabet="ox", min_size=n, max_size=n)))
    # Bias toward edge cases: occasionally all-o or all-x grids
    mode = draw(st.integers(0, 5))
    if mode == 0:
        rows = ["o" * n for _ in range(n)]
    elif mode == 1:
        rows = ["x" * n for _ in range(n)]
    return f"{n}\n" + "\n".join(rows) + "\n"

def validate(inp):
    lines = inp.split("\n")
    if len(lines) < 1:
        return False
    try:
        n = int(lines[0].strip())
    except Exception:
        return False
    if not (2 <= n <= 2000):
        return False
    rows = lines[1:1 + n]
    if len(rows) != n:
        return False
    for r in rows:
        if len(r) != n or any(c not in "ox" for c in r):
            return False
    return True

def ref(inp):
    lines = inp.split("\n")
    n = int(lines[0].strip())
    grid = [lines[1 + i].strip() for i in range(n)]
    cells = [(i, j) for i in range(n) for j in range(n) if grid[i][j] == "o"]
    count = 0
    for a, b, c in combinations(cells, 3):
        trip = [a, b, c]
        rows = {p[0] for p in trip}
        cols = {p[1] for p in trip}
        # exactly two in same row <=> exactly 2 distinct rows among the three
        # exactly two in same column <=> exactly 2 distinct columns among the three
